/**
 * Input checks for 「キーをインポート」 (POST /api/keys/import → Garage
 * ImportKey). They mirror Key::import in Garage v2.4.1
 * (src/model/key_table.rs), which the backend enforces too:
 *
 * - accessKeyId: at least 8 characters, ASCII alphanumerics and "-_."
 * - secretAccessKey: at least 16 characters, graphic ASCII (U+0021..U+007E)
 *
 * Keys generated by Garage itself are "GK" + 24 hex and a 64-hex secret;
 * anything else is accepted by Garage but only flagged as a warning here.
 */

export interface ImportKeyForm {
  name: string
  accessKeyId: string
  secretAccessKey: string
}

export interface ImportKeyBody {
  accessKeyId: string
  secretAccessKey: string
  name: string | null
}

export interface ImportKeyValidation {
  /** Blocking errors per field (absent when the field is acceptable). */
  errors: { accessKeyId?: string; secretAccessKey?: string }
  /** Non-blocking: the pair does not look like a key Garage generated. */
  warnings: { accessKeyId?: string; secretAccessKey?: string }
  /** The request body to send, or null while there is an error. */
  body: ImportKeyBody | null
}

const KEY_ID_RE = /^[A-Za-z0-9._-]+$/
const SECRET_RE = /^[\x21-\x7e]+$/
const GARAGE_KEY_ID_RE = /^GK[0-9a-f]{24}$/
const GARAGE_SECRET_RE = /^[0-9a-f]{64}$/

function keyIdError(id: string): string | undefined {
  if (id === '') return 'アクセスキー ID を入力してください'
  if (id.length < 8) return 'アクセスキー ID は 8 文字以上必要です'
  if (!KEY_ID_RE.test(id)) return 'アクセスキー ID に使えるのは英数字と - _ . だけです'
  return undefined
}

function secretError(secret: string): string | undefined {
  if (secret === '') return 'シークレットアクセスキーを入力してください'
  if (secret.length < 16) return 'シークレットアクセスキーは 16 文字以上必要です'
  if (!SECRET_RE.test(secret)) {
    return 'シークレットアクセスキーに使えるのは空白を除く ASCII 文字だけです'
  }
  return undefined
}

/**
 * Validates the form. Surrounding whitespace (a pasted trailing newline) is
 * dropped from the ID and the secret: neither may contain whitespace anyway.
 * An empty name is sent as null so Garage applies its default.
 */
export function validateImportKey(form: ImportKeyForm): ImportKeyValidation {
  const accessKeyId = form.accessKeyId.trim()
  const secretAccessKey = form.secretAccessKey.trim()
  const errors: ImportKeyValidation['errors'] = {}
  const warnings: ImportKeyValidation['warnings'] = {}

  const idErr = keyIdError(accessKeyId)
  if (idErr) errors.accessKeyId = idErr
  else if (!GARAGE_KEY_ID_RE.test(accessKeyId)) {
    warnings.accessKeyId = 'Garage が発行する形式 (GK + 16 進 24 桁) ではありません'
  }

  const secretErr = secretError(secretAccessKey)
  if (secretErr) errors.secretAccessKey = secretErr
  else if (!GARAGE_SECRET_RE.test(secretAccessKey)) {
    warnings.secretAccessKey = 'Garage が発行する形式 (16 進 64 桁) ではありません'
  }

  const ok = !errors.accessKeyId && !errors.secretAccessKey
  const name = form.name.trim()
  return {
    errors,
    warnings,
    body: ok ? { accessKeyId, secretAccessKey, name: name === '' ? null : name } : null,
  }
}
